style.css:
@-moz-document domain("10fastfingers.com") {
body {
    background-color: #1e1e2e !important;
    color: #f5f5f5 !important;
    font-family: Arial, sans-serif;
  }

  #row1, #row2, #row3 {
    background-color: #2c2c3c !important;
    color: #e0e0e0 !important;
  }

  .highlight {
    background-color: #44475a !important;
    color: #ffffff !important;
  }

  input, button, select {
    background-color: #3b3b4d !important;
    color: #f5f5f5 !important;
    border: 1px solid #666 !important;
  }

  .word {
    color: #cccccc !important;
  }

  .word.highlight {
    background-color: #5e5e77 !important;
    color: #ffffff !important;
  }

  #gameWrapper {
    display: flex !important;
    justify-content: center !important;
    align-items: center !important;
    flex-direction: column !important;
    padding: 20px;
  }

  .container {
    max-width: 900px !important;
    margin: auto !important;
  }

  #inputfield {
    background-color: #2c2c3c !important;
    color: #ffffff !important;
  }

  #reloadBtn, #newGameBtn {
    background-color: #44475a !important;
    color: #ffffff !important;
    border: none !important;
    padding: 8px 16px;
    border-radius: 4px;
    cursor: pointer;
  }

  #reloadBtn:hover, #newGameBtn:hover {
    background-color: #6272a4 !important;
  }
}
